import { type ButtonHTMLAttributes, forwardRef } from 'react';
import { clsx, type ClassValue } from 'clsx';
import { Loader2 } from 'lucide-react';

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger';
  size?: 'sm' | 'md' | 'lg' | 'icon';
  isLoading?: boolean;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  fullWidth?: boolean;
}

/**
 * Enterprise Button Component
 * - Supports multiple variants and sizes
 * - Built-in loading state with spinner
 * - Icon support (left/right)
 * - Accessible focus ring and disabled states
 */
export function buttonVariants({ variant = 'primary', size = 'md', fullWidth, className }: Partial<ButtonProps> = {}) {
  const baseStyles: ClassValue =
    'inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50';

  const variants: Record<NonNullable<ButtonProps['variant']>, ClassValue> = {
    primary:
      'bg-orange-500 text-white hover:bg-orange-600 focus-visible:ring-orange-500 shadow-sm',
    secondary:
      'bg-navy-800 text-white hover:bg-navy-700 focus-visible:ring-navy-800 shadow-sm',
    outline:
      'border border-gray-300 bg-transparent hover:bg-gray-100 focus-visible:ring-gray-400 text-gray-900',
    ghost: 'hover:bg-gray-100 hover:text-gray-900 text-gray-600 focus-visible:ring-gray-400',
    danger: 'bg-red-500 text-white hover:bg-red-600 focus-visible:ring-red-500 shadow-sm',
  };

  const sizes: Record<NonNullable<ButtonProps['size']>, ClassValue> = {
    sm: 'h-8 px-3 text-xs',
    md: 'h-10 px-4 py-2',
    lg: 'h-12 px-8 text-base',
    icon: 'h-10 w-10',
  };

  const widthClass = fullWidth ? 'w-full' : '';

  return clsx(baseStyles, variants[variant as NonNullable<ButtonProps['variant']>], sizes[size as NonNullable<ButtonProps['size']>], widthClass, className);
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant = 'primary',
      size = 'md',
      isLoading = false,
      leftIcon,
      rightIcon,
      fullWidth,
      disabled,
      children,
      type = 'button',
      ...props
    },
    ref,
  ) => {
    return (
      <button
        ref={ref}
        type={type}
        disabled={disabled ?? isLoading}
        className={buttonVariants({ variant, size, fullWidth, className })}
        {...props}
      >
        {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />}
        {!isLoading && leftIcon && <span className="mr-2">{leftIcon}</span>}
        {children}
        {!isLoading && rightIcon && <span className="ml-2">{rightIcon}</span>}
      </button>
    );
  },
);

Button.displayName = 'Button';

import { memo } from 'react';
import { Link } from 'react-router';
import { Container } from '@/components/ui/Container';
import { buttonVariants } from '@/components/ui/Button';
import type { ServiceBlockProps } from '../registry/BlockRenderer';
import { useContactNavigation } from '../hooks/useContactNavigation';

export const CTASection = memo(function CTASection({ entity }: ServiceBlockProps) {
  const { navigateToContact, buildContactUrl } = useContactNavigation();

  const headline = entity.marketing?.headline ?? 'Ready to Optimize Your Facility?';
  const ctaText = entity.marketing?.ctaText ?? 'Request a Free Consultation';
  const isService = 'categoryId' in entity;
  const categoryId = isService ? (entity as any).categoryId : undefined;

  return (
    <section className="py-24 bg-navy-900 relative overflow-hidden">
      {/* Abstract Background pattern */}
      <div className="absolute inset-0 opacity-10">
        <svg className="w-full h-full" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <pattern id="grid-pattern" width="40" height="40" patternUnits="userSpaceOnUse">
              <path d="M0 40L40 0H20L0 20M40 40V20L20 40" stroke="white" strokeWidth="1" fill="none" />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#grid-pattern)" />
        </svg>
      </div>

      <Container size="md" className="relative z-10 text-center">
        <h2 className="text-3xl md:text-5xl font-bold text-white mb-6 leading-tight">
          {headline}
        </h2>
        <p className="text-lg text-gray-300 mb-10 max-w-2xl mx-auto">
          Partner with Kargar to ensure your enterprise operations run smoothly, safely, and efficiently. Our experts are ready to design a tailored solution for your specific needs.
        </p>
        <Link
          className={buttonVariants({ variant: 'primary', size: 'lg', className: 'shadow-lg hover:shadow-orange-500/20 px-8 py-4 text-lg' })}
          to={buildContactUrl({
            source: 'cta_section',
            service: entity.slug,
            category: categoryId,
            ctaPosition: 'bottom',
          })}
          onClick={(e) => { navigateToContact({
            source: 'cta_section',
            service: entity.slug,
            category: categoryId,
            ctaPosition: 'bottom',
          }, e); }}
        >
          {ctaText}
        </Link>
      </Container>
    </section>
  );
});

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unnecessary-condition, @typescript-eslint/prefer-nullish-coalescing */
import { memo } from 'react';
import { Container } from '@/components/ui/Container';
import { SectionHeading } from '@/components/ui/SectionHeading';
import type { ServiceBlockProps } from '../registry/BlockRenderer';
import { useServices } from '../hooks/useServices';
import * as LucideIcons from 'lucide-react';
import type { Service } from '../domain/service.types';

interface ExtendedEntity {
  industries?: { title: string; iconKey?: string }[] | string[];
  operations?: { equipmentMaintained?: { name: string; iconKey?: string }[] };
  relationships?: { relatedServices?: string[] };
}

export const CollectionSection = memo(function CollectionSection({ entity, block }: ServiceBlockProps) {
  const { getServicesByCategory, getService } = useServices();
  const serviceEntity = entity as unknown as ExtendedEntity;

  const bgClass = block.background === 'light' ? 'bg-slate-50' 
                : block.background === 'dark' ? 'bg-navy-900' 
                : 'bg-white';

  const renderVariant = () => {
    switch (block.variant) {
      case 'industry': {
        const industries = serviceEntity.industries || [];
        if (industries.length === 0) return null;

        return (
          <>
            <SectionHeading title="Industries Served" eyebrow="Our Expertise" align="center" className="mb-12" />
            <div className="flex flex-wrap justify-center gap-4">
              {industries.map((industry, i: number) => {
                const title = typeof industry === 'string' ? industry : industry.title;
                return (
                  <div key={i} className="px-6 py-3 bg-white border border-slate-200 rounded-full text-navy-900 font-medium hover:border-orange-500 hover:text-orange-500 transition-colors cursor-default shadow-sm hover:shadow-md">
                    {title}
                  </div>
                );
              })}
            </div>
          </>
        );
      }
      case 'equipment': {
        const equipment = serviceEntity.operations?.equipmentMaintained || [];
        if (equipment.length === 0) return null;

        return (
          <>
            <SectionHeading title="Equipment We Maintain" eyebrow="Technical Capabilities" align="center" className="mb-12" />
            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-6">
              {equipment.map((eq, i: number) => {
                const iconKey = eq.iconKey || 'wrench';
                const findIcon = (key: string) => {
                  const iconName = Object.keys(LucideIcons).find(
                    (name) => name.toLowerCase() === key.toLowerCase().replace(/-/g, '')
                  );
                  return iconName ? LucideIcons[iconName as keyof typeof LucideIcons] as React.ElementType : LucideIcons.Wrench;
                };
                const IconComponent = findIcon(iconKey);
                return (
                  <div key={i} className="flex flex-col items-center justify-center p-6 bg-white border border-slate-100 rounded-xl hover:shadow-lg transition-all text-center group cursor-default">
                    <div className="w-12 h-12 bg-orange-50 text-orange-600 rounded-lg flex items-center justify-center mb-4 group-hover:bg-orange-500 group-hover:text-white transition-colors duration-300">
                      <IconComponent size={24} />
                    </div>
                    <h3 className="font-semibold text-slate-800 text-sm">{eq.name}</h3>
                  </div>
                );
              })}
            </div>
          </>
        );
      }
      case 'service':
      case 'related': {
        let services: Service[] = [];
        let title = '';
        let eyebrow = '';

        if (block.variant === 'related') {
          title = 'Related Services';
          eyebrow = 'Discover More';
          const relatedIds = serviceEntity.relationships?.relatedServices || [];
          services = relatedIds.map((id: string) => getService(id)!).filter(Boolean);
        } else {
          // 'service' variant means list children services for a category
          title = 'Included Services';
          eyebrow = 'What We Offer';
          services = getServicesByCategory(entity.id);
        }

        if (services.length === 0) return null;

        return (
          <>
             <SectionHeading title={title} eyebrow={eyebrow} align="center" className="mb-12" />
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
               {services.map((service) => (
                 <a key={service.id} href={`/services/${service.categoryId}-services/${service.slug}`} className="group block bg-white rounded-2xl overflow-hidden border border-slate-100 shadow-sm hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1">
                   <div className="p-8">
                     <div className="w-14 h-14 bg-navy-50 rounded-xl flex items-center justify-center text-navy-900 mb-6 group-hover:bg-navy-900 group-hover:text-white transition-colors">
                       <LucideIcons.Layers size={28} />
                     </div>
                     <h3 className="text-xl font-bold text-navy-900 mb-3">{service.title}</h3>
                     <p className="text-slate-600 line-clamp-3 leading-relaxed mb-6">{service.shortDescription}</p>
                     <div className="flex items-center text-orange-600 font-bold group-hover:gap-2 transition-all">
                       Learn More <LucideIcons.ArrowRight size={18} className="ml-1 group-hover:translate-x-1 transition-transform" />
                     </div>
                   </div>
                 </a>
               ))}
             </div>
          </>
        );
      }
      default:
        return null;
    }
  };

  const content = renderVariant();
  if (!content) return null;

  return (
    <section id={block.id} className={`py-20 lg:py-28 ${bgClass}`}>
      <Container size="xl">
        {content}
      </Container>
    </section>
  );
});

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unnecessary-condition, @typescript-eslint/prefer-nullish-coalescing */
import { memo } from 'react';
import { Container } from '@/components/ui/Container';
import { SectionHeading } from '@/components/ui/SectionHeading';
import type { ServiceBlockProps } from '../registry/BlockRenderer';
import * as LucideIcons from 'lucide-react';

interface FeatureItem {
  title: string;
  description?: string;
  iconKey?: string;
}

interface ExtendedEntity {
  whyChooseUs?: FeatureItem[];
  challenges?: FeatureItem[];
  solutions?: FeatureItem[];
  benefits?: FeatureItem[];
  compliance?: FeatureItem[];
  operations?: { scopeOfWork?: FeatureItem[], deliverables?: FeatureItem[] };
  process?: FeatureItem[];
  features?: FeatureItem[];
}

export const FeatureGridSection = memo(function FeatureGridSection({ entity, block }: ServiceBlockProps) {
  // Map block id to the correct data array on the entity
  let items: FeatureItem[] = [];
  let title = '';
  let eyebrow = '';

  const serviceEntity = entity as unknown as ExtendedEntity;
  switch (block.id) {
    case 'why-us':
      items = serviceEntity.whyChooseUs || [];
      title = 'Why Choose Kargar';
      eyebrow = 'The Enterprise Advantage';
      break;
    case 'challenges':
      items = serviceEntity.challenges || [];
      title = 'Business Challenges';
      eyebrow = 'Understanding Your Needs';
      break;
    case 'solutions':
      items = serviceEntity.solutions || [];
      title = 'Our Solutions';
      eyebrow = 'How We Fix It';
      break;
    case 'benefits':
      items = serviceEntity.benefits || serviceEntity.whyChooseUs || [];
      title = 'Key Benefits';
      eyebrow = 'What You Get';
      break;
    case 'compliance':
      items = serviceEntity.compliance || [];
      title = 'Compliance & Standards';
      eyebrow = 'Safety First';
      break;
    case 'scope':
      items = serviceEntity.operations?.scopeOfWork || [];
      title = 'Scope of Work';
      eyebrow = 'What We Do';
      break;
    case 'deliverables':
      items = serviceEntity.operations?.deliverables || [];
      title = 'Key Deliverables';
      eyebrow = 'Measurable Results';
      break;
    case 'process':
      items = serviceEntity.process || [];
      title = 'Our Process';
      eyebrow = 'How It Works';
      break;
    case 'features':
      items = serviceEntity.features || [];
      title = 'Key Features';
      eyebrow = 'What Makes Us Different';
      break;
    default:
      break;
  }

  if (!items || items.length === 0) return null;

  const bgClass = block.background === 'light' ? 'bg-slate-50' 
                : block.background === 'dark' ? 'bg-navy-900' 
                : 'bg-white';

  const renderVariant = () => {
    switch (block.variant) {
      case 'checklist':
        return (
          <div className="grid md:grid-cols-2 gap-x-12 gap-y-6 max-w-4xl mx-auto">
            {items.map((item, i) => (
              <div key={i} className="flex items-start gap-4">
                <div className="mt-1 flex-shrink-0 w-6 h-6 rounded-full bg-green-100 text-green-600 flex items-center justify-center">
                   <LucideIcons.Check size={14} strokeWidth={3} />
                </div>
                <div>
                  <h3 className="text-lg font-bold text-navy-900 mb-1">{item.title}</h3>
                  {item.description && <p className="text-slate-600">{item.description}</p>}
                </div>
              </div>
            ))}
          </div>
        );

      case 'list':
      case 'timeline':
        return (
          <div className="max-w-3xl mx-auto space-y-8">
            {items.map((item, i) => (
              <div key={i} className="flex gap-6">
                <div className="flex flex-col items-center">
                  <div className="w-10 h-10 rounded-full bg-orange-100 text-orange-600 flex items-center justify-center font-bold">
                    {i + 1}
                  </div>
                  {i < items.length - 1 && <div className="w-px h-full bg-orange-100 my-2" />}
                </div>
                <div className="pb-8">
                  <h3 className="text-xl font-bold text-navy-900 mb-2">{item.title}</h3>
                  {item.description && <p className="text-slate-600 leading-relaxed">{item.description}</p>}
                </div>
              </div>
            ))}
          </div>
        );

      case 'highlight':
      case 'cards':
      default:
        return (
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
            {items.map((item, i) => {
              const iconKey = item.iconKey || 'check-circle';

              // Helper function to find icon (case-insensitive)
              const findIcon = (key: string) => {
                const iconName = Object.keys(LucideIcons).find(
                  (name) => name.toLowerCase() === key.toLowerCase().replace(/-/g, '')
                );
                return iconName ? LucideIcons[iconName as keyof typeof LucideIcons] as React.ElementType : LucideIcons.CheckCircle;
              };

              const IconComponent = findIcon(iconKey);

              return (
                <div key={i} className="bg-white p-8 rounded-2xl border border-slate-100 shadow-sm hover:shadow-lg transition-all duration-300 group">
                  <div className="w-14 h-14 bg-orange-50 text-orange-600 rounded-xl flex items-center justify-center mb-6 group-hover:bg-orange-600 group-hover:text-white transition-colors duration-300">
                    <IconComponent size={28} />
                  </div>
                  <h3 className="text-xl font-bold text-navy-900 mb-3">{item.title}</h3>
                  {item.description && <p className="text-slate-600 leading-relaxed">{item.description}</p>}
                </div>
              );
            })}
          </div>
        );
    }
  };

  return (
    <section id={block.id} className={`py-20 lg:py-28 ${bgClass}`}>
      <Container size="xl">
        <SectionHeading 
          title={title} 
          eyebrow={eyebrow}
          align="center"
          className="mb-16"
        />
        {renderVariant()}
      </Container>
    </section>
  );
});

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unnecessary-condition, @typescript-eslint/prefer-nullish-coalescing */
import { memo } from 'react';
import { Container } from '@/components/ui/Container';
import { SectionHeading } from '@/components/ui/SectionHeading';
import { OptimizedImage } from '@/components/ui/OptimizedImage';
import type { ServiceBlockProps } from '../registry/BlockRenderer';

export const GallerySection = memo(function GallerySection({ entity, block }: ServiceBlockProps) {
  const gallery = (entity as unknown as { gallery?: any[] }).gallery;

  if (!gallery || gallery.length === 0) return null;

  const bgClass = block.background === 'light' ? 'bg-slate-50' 
                : block.background === 'dark' ? 'bg-navy-900' 
                : 'bg-white';

  return (
    <section id={block.id} className={`py-20 lg:py-28 ${bgClass}`}>
      <Container size="xl">
        <SectionHeading 
          title="Our Work in Action" 
          eyebrow="Gallery"
          align="center"
          className="mb-12"
        />

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
          {gallery.map((imageKey: string, i: number) => {
             // Ideally we map imageKey to a real asset from the Asset Registry
             // For now, we will use placeholder structural images
             const src = `/assets/services/gallery/${imageKey}.webp`;
             return (
               <div key={i} className="relative aspect-square rounded-2xl overflow-hidden bg-slate-200 group">
                 {/* 
                   Fallback placeholder if asset missing. In real app, OptimizedImage will handle fallback.
                 */}
                 <OptimizedImage 
                   src={src}
                   alt={`Gallery image ${i + 1}`}
                   className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                 />
                 <div className="absolute inset-0 bg-navy-900/0 group-hover:bg-navy-900/20 transition-colors duration-300" />
               </div>
             );
          })}
        </div>
      </Container>
    </section>
  );
});

/* eslint-disable @typescript-eslint/no-unnecessary-type-arguments, @typescript-eslint/no-unnecessary-type-assertion, @typescript-eslint/prefer-optional-chain, @typescript-eslint/no-unnecessary-condition, @typescript-eslint/prefer-nullish-coalescing */
import { memo } from 'react';
import { Link } from 'react-router';
import { Container } from '@/components/ui/Container';
import { Button, buttonVariants } from '@/components/ui/Button';
import { OptimizedImage } from '@/components/ui/OptimizedImage';
import { Breadcrumb } from './Breadcrumb';
import { useContactNavigation } from '../hooks/useContactNavigation';
import { serviceImages } from '../config/images';
import type { ServiceBlockProps } from '../registry/BlockRenderer';
import type { Service } from '../domain/service.types';

export const HeroSection = memo(function HeroSection({ entity, block }: ServiceBlockProps) {
  const image = serviceImages[entity.imageKey] ?? serviceImages.hardServices;
  const { navigateToContact, buildContactUrl } = useContactNavigation();

  const isService = 'categoryId' in entity;
  const breadcrumbs = [
    { label: 'Home', href: '/' },
    { label: 'Services', href: '/services' },
  ];

  if (isService) {
    const service = entity as Service;
    breadcrumbs.push({ 
      label: service.categoryId === 'hard' ? 'Hard Services' : 'Soft Services', 
      href: `/services/${service.categoryId}-services` 
    });
    breadcrumbs.push({ label: service.title, href: '#' });
  } else {
    breadcrumbs.push({ label: entity.title, href: '#' });
  }

  const title = entity.marketing?.headline ?? entity.title;
  const subtitle = entity.marketing?.summary ?? ('shortDescription' in entity ? (entity as unknown as { shortDescription: string }).shortDescription : '');
  const ctaText = entity.marketing?.ctaText ?? 'Request Proposal';

  const serviceType = isService ? (entity as Service).serviceType : 'technical';
  const variant = block.variant || `hero${serviceType.charAt(0).toUpperCase() + serviceType.slice(1)}`;

  // Example variants (Technical vs Cleaning vs Security)
  const renderRightContent = () => {
    if (variant === 'heroCleaning') {
      return (
        <div className="hidden lg:flex flex-col gap-4 flex-1 items-end pt-12">
           <div className="bg-white/10 backdrop-blur-md border border-white/10 p-6 rounded-2xl w-80">
            <h3 className="text-white font-bold text-2xl mb-2 flex items-center gap-2">
              <span className="text-green-400">✓</span> Eco-Friendly
            </h3>
            <p className="text-gray-300 text-sm leading-relaxed">Using sustainable, non-toxic cleaning agents for a safer workspace.</p>
          </div>
        </div>
      );
    }
    if (variant === 'heroSecurity') {
      return (
        <div className="hidden lg:flex flex-col gap-4 flex-1 items-end pt-12">
          <div className="bg-white/10 backdrop-blur-md border border-white/10 p-6 rounded-2xl w-80 text-center">
             <div className="mx-auto bg-blue-500/20 w-16 h-16 rounded-full flex items-center justify-center mb-4 border border-blue-400/30">
                <span className="text-blue-400 text-2xl">🛡️</span>
             </div>
            <h3 className="text-white font-bold text-xl mb-1">24/7 Protection</h3>
            <p className="text-gray-300 text-sm">Rapid response security personnel.</p>
          </div>
        </div>
      );
    }

    // Default / Technical
    return (
      <div className="hidden lg:flex flex-col gap-4 flex-1 items-end pt-12">
        <div className="bg-white/10 backdrop-blur-md border border-white/10 p-6 rounded-2xl w-72 transform rotate-2 hover:rotate-0 transition-transform">
          <h3 className="text-white font-bold text-2xl mb-1">99%</h3>
          <p className="text-gray-300 text-sm">SLA Compliance Rate</p>
        </div>
        <div className="bg-white/10 backdrop-blur-md border border-white/10 p-6 rounded-2xl w-72 transform -rotate-1 hover:rotate-0 transition-transform -mr-8">
          <h3 className="text-white font-bold text-2xl mb-1">24/7</h3>
          <p className="text-gray-300 text-sm">Emergency Support</p>
        </div>
      </div>
    );
  };

  return (
    <section id={block.id} className="relative bg-navy-900 overflow-hidden py-16 md:py-24">
      {/* Background Image with Overlay */}
      <div className="absolute inset-0 z-0">
        <OptimizedImage
          src={image?.src ?? ''}
          alt={image?.alt ?? title}
          className="w-full h-full object-cover opacity-20"
        />
        <div className="absolute inset-0 bg-linear-to-r from-navy-900 via-navy-900/90 to-transparent" />
      </div>

      <Container size="xl" className="relative z-10 flex flex-col lg:flex-row items-center gap-12">
        {/* Left Side: Content */}
        <div className="flex-1 max-w-3xl">
          <div className="mb-6 opacity-80 mix-blend-screen text-white/80 [&_a]:text-white/80 [&_span]:text-white">
            <Breadcrumb items={breadcrumbs} />
          </div>

          <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold text-white mb-6 leading-tight max-w-[800px]">
            {title}
          </h1>

          {subtitle && (
            <p className="text-lg md:text-xl text-gray-300 mb-8 max-w-2xl leading-relaxed">
              {subtitle}
            </p>
          )}

          <div className="flex flex-wrap gap-4">
            <Link
              className={buttonVariants({ variant: 'primary', size: 'lg', className: 'shadow-lg hover:shadow-orange-500/20' })}
              to={buildContactUrl({
                source: 'hero',
                service: entity.slug,
                category: isService ? (entity as Service).categoryId : undefined,
                ctaPosition: 'hero',
              })}
              onClick={(e) => { navigateToContact({
